insert into public.reviews (product_id, shop_id, author_name, author_meta, initials, rating, body, featured, created_at) values
((select id from public.products where slug='lingotin-2g-24ct'),'a0000000-0000-4000-8000-000000000001','Rasmata Kaboré','Lingotin 2 g · Ouagadougou','RK',5,'J''ai acheté mon premier lingotin de 2 g. Le conseiller m''a tout expliqué au téléphone, et le certificat était dans le colis.',true, now() - interval '12 days'),
((select id from public.products where slug='alliance-wend-panga'),'a0000000-0000-4000-8000-000000000012','Aminata & Oumar Sanou','Alliances 18 ct · Bobo-Dioulasso','AS',5,'Nos alliances ont été gravées par Maison Ouédraogo et livrées à Bobo quatre jours avant le mariage. Scellé intact.',true, now() - interval '20 days'),
(null,null,'Seydou Zongo','Bijoutier vérifié · Koudougou','SZ',5,'En tant que bijoutier, la vérification de mon atelier m''a apporté des clients d''Abidjan et de Bamako.',true, now() - interval '30 days'),
