insert into public.faqs (question, answer, category, featured, sort) values
('Puis-je vraiment acheter seulement 1 g d''or ?','Oui. Nos lingotins officiels commencent à 1 g, en or 24 carats (999,9 ‰), livrés sous scellé avec leur certificat d''analyse.','Acheter',true,1),
('Comment le prix est-il calculé ?','Prix = cours du jour × poids + façon (fabrication, frappe) + livraison sécurisée. Chaque ligne est affichée avant le paiement, et le prix est garanti 15 minutes.','Prix',true,2),
('Que signifie « Vérifié » ou « Déclaré » ?','« Vérifié par Burkina Or » : la caractéristique a été contrôlée par analyse. « Déclaré par le vendeur » : elle est fournie par le vendeur, sans contrôle de notre part.','Confiance',true,3),
('Comment se passe la livraison ?','Votre colis est scellé, assuré à sa valeur et suivi étape par étape. Il ne vous est remis que contre votre code sécurisé à 4 chiffres.','Livraison',true,4),
('Puis-je revendre mon or ?','Oui, via nos comptoirs partenaires vérifiés. Un conseiller peut vous accompagner pour obtenir une offre au cours du jour.','Revendre',true,5),
('Quelle différence entre 24, 22 et 18 carats ?','Le carat exprime la proportion d''or pur : 24 ct = 999,9 ‰, 22 ct = 916 ‰, 18 ct = 750 ‰. Plus le titre est élevé, plus l''or est pur mais aussi plus tendre ; le 18 ct est privilégié en bijouterie pour sa résistance.','Comprendre l''or',false,6),
('Quels documents dois-je demander lors d''un achat ?','Pour un lingotin : le certificat d''analyse indiquant poids, pureté et numéro de série. Pour un bijou : la facture détaillée mentionnant le titre et le poids d''or. Sur Burkina Or, ces informations sont affichées sur chaque fiche.','Confiance',false,7),
('Quels moyens de paiement acceptez-vous ?','Orange Money, Moov Money, Wave, cartes Visa et Mastercard (3-D Secure), virement bancaire et paiement en agence (espèces ou chèque certifié).','Paiement',false,8),
('Puis-je annuler ma commande ?','Oui, la rétractation est possible sous 48 h tant que le colis n''a pas été expédié. Les créations sur mesure engagées ne sont pas annulables.','Retours',false,9),
('Que faire si le scellé est abîmé à la livraison ?','Refusez le colis et ne communiquez pas votre code de remise. Signalez immédiatement l''incident depuis votre espace client : une enquête est ouverte et vous êtes remboursé ou relivré.','Livraison',false,10),
('Comment devenir vendeur sur Burkina Or ?','Créez un compte professionnel, choisissez votre activité (bijoutier, comptoir, fondeur ou livreur) et déposez vos pièces justificatives. Notre équipe conformité valide votre dossier sous 48 h.','Professionnels',false,11),
('Quelles commissions sont prélevées ?','Les commissions sont prélevées sur le prix vendeur, jamais ajoutées au prix client : 8 % sur les bijoux, 10 % sur le sur-mesure, 2 % sur les offres de gros, 6 % sur les services.','Professionnels',false,12),
('Livrez-vous hors du Burkina Faso ?','Oui, dans 7 pays d''Afrique de l''Ouest (Côte d''Ivoire, Mali, Niger, Togo, Ghana, Sénégal) par transporteur de valeurs, en 4 à 7 jours.','Livraison',false,13);
